#[test]
fn every_captured_burst_still_decodes() {
    // These are the reference units' own bursts, so the policy under test is the
    // real one: declared devices only. If a fixture ever needed `+legacy` or a
    // blanket allow to decode, that would itself be the regression.
    let policy = Policy::from_map(&revivint_core::KEYS);
    let accepts = |fr: &revivint_core::DecodedFrame| policy.accepts_bare(fr);
    let mut decoded = 0;
    for (i, f) in FIXTURES.iter().enumerate() {
        let mut chips = BitBuf::new();
        manchester::pulses_to_chips(f.pulses, &mut chips);
        let mut hit = None;
        for invert in [false, true] {
            manchester::for_each_run(chips.as_slice(), invert, |bits| {
                if hit.is_none() {
                    for_each_frame_in_run_vetted(bits, accepts, |fr, _| hit = Some(*fr));
                }
            });
            if hit.is_some() {
                break;
            }
        }
        let fr = hit.unwrap_or_else(|| panic!("fixture {i} no longer decodes"));
        assert_eq!(fr.txid, f.txid, "fixture {i} txid");
        assert_eq!(fr.counter(), Some(f.counter), "fixture {i} counter");
        assert_eq!(fr.type_byte(), f.type_byte, "fixture {i} type");
        assert!(fr.crc_ok, "fixture {i} crc");
        decoded += 1;
    }
    assert_eq!(decoded, FIXTURES.len());
}
